Set error = {}

If obj.%Get("User") = "" {
	set ^webService("ValidateJSONForDisplayColumns") = "User was blank"
	Set error.errormessage = "User was blank"
	Quit 0
}	

set ^webService("ValidateJSONForDisplayColumns") = "ValidateJSONForDisplayColumns: " _ obj.%Get("User")
Quit 1

	set ^webService("CopyDisplayColumnsFromJSON User: ") = obj.User
	set deleteRows = 1

	set iter = obj.displayColumns.%GetIterator()

    while iter.%GetNext(.key , .value ) {
	    if (value.TransactionCode '= "")
	    {
		  	set cm = ##class(IHC.ITF.ITFCOMMON.X12.DisplayColumns).%New()
			Set cm.User=obj.User
			set cm.TransactionCode = value.TransactionCode
			Set cm.Key = value.key
			set cm.Order = value.Order	
			if (deleteRows = 1)
			{
					Set rs = ##class(%SQL.Statement).%ExecDirect(,"DELETE IHC_ITF_ITFCOMMON_X12.DisplayColumns where user = '" _ obj.User _ "' AND TransactionCode = '" _value.TransactionCode _ "'")
					Set deleteRows = 0
			}

			Set sc = cm.%Save()
			do result.%Set("Status",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))
			if ($$$ISOK(sc)) {
				set ^webService("CopyDisplayColumnsFromJSON Added") = cm.%Id()	
				do result.%Set("id", cm.%Id())
			}
			else
			{
				set ^webService("CopyDisplayColumnsFromJSON Error") = sc
				QUIT
			}
	    }

    }

Set ok = 1
Try {
	Set obj = ##class(%DynamicObject).%FromJSON(%request.Content)
	set ^webService("GetJSONFromRequest ") = obj
} Catch ex {
	Set ok = 0
}
Quit ok
